{"code":"import csv

# CSV içeriğini doğrudan okuyup yazdıralım
try:
    with open('rapor.csv', 'r', encoding='utf-8') as f:
        reader = csv.reader(f)
        header = next(reader)
        print(f"Başlık: {header}")
        print("-" * 30)
        for row in reader:
            print(f"{row[0]:<20} | {row[1]:>5} | {row[2]:>5} | {row[3]:>5}")
except Exception as e:
    print(f"Hata: {e}")
"}
